board=json.loads(r'''"\n  function mouthCoverageStats(look){\n    const rows=(C.mouthCoverage?.items||[]).filter(i=>i.lookID===look.id&&byID.get(i.assetID)?.sha256===i.sha256),numbers=new Set(rows.map(r=>r.number).filter(Number.isInteger));\n    const reviewed=rows.filter(r=>reviews.has(r.assetID)),accepted=rows.filter(r=>{const q=reviewRecord(r.assetID);return q.status==='keep'&&storyboardStage(byID.get(r.assetID))==='production';});\n    const validated=rows.filter(r=>{const latest=validationLatest(r.assetID,'character',r.validationScopeID)[0],check=latest&&validationAssessment(latest);return check?.status==='pass'&&check.current;});\n    return {rows,files:rows.length,distinctHashes:new Set(rows.map(r=>r.sha256)).size,labels:numbers.size,reviewed:reviewed.length,acceptedFiles:accepted.length,acceptedLabels:new Set(accepted.map(r=>r.number).filter(Number.isInteger)).size,validatedLabels:new Set(validated.map(r=>r.number).filter(Number.isInteger)).size,distinctUsable:null};\n  }\n  function mouthCoverageBoard(){\n    const board=C.mouthCoverage;if(!board)return '';\n    const looks=board.looks.filter(l=>l.project===state.project);\n    let html='<section class=\"mouth-coverage\" id=\"mouth-coverage-board\"><h3>Mouth coverage board</h3><p>What the animation recipe needs and what the artwork library contains are separate counts.</p><details><summary>Recipe input readiness · '+board.recipe.requiredStillAtlasSlots+' still-atlas slots required by this saved graph</summary><p>'+esc(board.recipe.title)+' · '+esc(board.recipe.checkpoint)+'</p><p><b>Mouth bank not consumed.</b> '+esc(board.recipe.clipEvidence)+'</p><ul>'+board.recipe.inputs.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p>'+esc(board.recipe.result)+' '+esc(board.recipe.lisanStatus)+'</p><p>'+esc(board.recipe.faceDriverConcern)+'</p><p><a href=\"'+esc(href('../../../../../../'+board.recipe.graph.path))+'\" target=\"_blank\" rel=\"noopener\">Exact saved graph</a> · SHA256 '+esc(board.recipe.graph.sha256)+'</p><p>'+esc(board.clipProofRequirements)+'</p></details><h4>Reference artwork coverage</h4><p>Provider labels mix articulation, expressions and actions. A repeated take, alias or view does not add a new mouth category. Usable distinct articulation remains unknown; still evidence never proves temporal speech.</p>';\n    for(const look of looks){\n      const stats=mouthCoverageStats(look),open=state.mouthLook===look.id;\n      html+='<div class=\"mouth-look\"><h4>'+esc(look.title)+'</h4><p>'+esc(look.stableLook)+'</p><div class=\"mouth-metrics\"><span>'+stats.files+' candidates / '+stats.distinctHashes+' distinct images</span><span>'+stats.labels+' / '+(look.plannedNumbers.length||'—')+' planned numbered categories</span><span>'+stats.acceptedFiles+' scoped Production takes / '+stats.acceptedLabels+' numbered categories</span><span>'+stats.validatedLabels+' evidence-validated static categories</span><span>Distinct usable: unknown</span></div><p>'+esc(look.planStatus)+'. '+esc(look.note)+'</p>';\n      if(look.referenceAssetID&&byID.has(look.referenceAssetID))html+='<button class=\"pill\" data-open=\"'+esc(look.referenceAssetID)+'\">Open selected scoped look</button>';\n      html+='<button class=\"pill\" data-mouth-look=\"'+esc(look.id)+'\" aria-expanded=\"'+open+'\">'+(open?'Close':'Open')+' coverage grid</button>';\n      if(open){\n        const keys=look.plannedNumbers.length?look.plannedNumbers:[...new Set(stats.rows.map(r=>r.number||r.assetID))],kinds=[['articulation','Core articulation labels'],['extended','Extended delivery / phonetic labels'],['expression','Expression / action labels'],['other','Accessory, history and unnumbered references']];\n        for(const [kind,title] of kinds){\n          const slots=keys.filter(n=>kind===(typeof n!=='number'?'other':board.articulationNumbers.includes(n)?'articulation':board.extendedNumbers.includes(n)?'extended':'expression'));if(!slots.length)continue;\n          html+='<details '+(kind==='articulation'?'open':'')+'><summary>'+title+' · '+slots.length+'</summary><div class=\"mouth-board-grid\">';\n          for(const number of slots){\n            const rows=stats.rows.filter(r=>(r.number||r.assetID)===number),first=rows[0]&&byID.get(rows[0].assetID);\n            const failures=rows.filter(r=>validationSummary(byID.get(r.assetID),'character').status==='fail'||reviewRecord(r.assetID).status==='needs_fixes');\n            html+='<article class=\"mouth-slot\"><b>'+esc(typeof number==='number'?String(number).padStart(2,'0'):'Reference')+' · '+esc(rows[0]?.label||'Missing candidate')+'</b>'+(first?'<img loading=\"lazy\" src=\"'+esc(href(first.thumb||first.src))+'\" alt=\"'+esc(first.title)+'\">':'')+'<p>'+rows.length+' takes · '+(rows.length?(failures.length?'Needs repair / unresolved':'Unchecked unless scoped evidence shown'):'Missing')+'</p>';\n            for(const row of rows){\n              const a=byID.get(row.assetID),v=validationSummary(a,'character');\n              html+='<button class=\"small-link\" data-open=\"'+esc(a.id)+'\">'+esc(a.id)+' · '+esc(row.revision)+'</button><p>'+esc(v.label)+' · '+esc(row.yaw)+' / '+esc(row.pitch)+'</p>';\n              const notes=board.observations.filter(o=>o.assetID===a.id);for(const note of notes)html+='<details><summary>Attributed pixel observation</summary><p>'+esc(note.observation)+'</p><small>'+esc(note.reviewer.actor)+' · '+esc(note.documentAtUTC)+' · '+esc(note.surface)+' · source '+esc(note.source.sha256)+'</small></details>';\n            }\n            if(look.id==='hon-external-off'&&[9,10].includes(number))html+='<p>09/10: different bytes, overlapping teeth-baring poses. Distinct articulation uncertain; both original reviews retained.</p>';\n            if(rows.length>1)html+='<p>Multiple takes share this provider label. Different bytes do not establish different articulation.</p>';\n            html+='</article>';\n          }\n          html+='</div></details>';\n        }\n        html+='<details><summary>Yaw, pitch, stable look and jewelry are separate axes</summary><p>'+esc(board.headPlan.note)+'</p><p>Recorded head-state slots: '+board.headPlan.receivedSlots+' / '+board.headPlan.baseSlots+'. Optional expansion: '+board.headPlan.expandedUniqueSlots+' unique slots; key-state selection is not accepted.</p><p>Unknown angle/revision fields stay unknown. No opposite view is inferred by mirroring, and macros do not fill head slots.</p></details>';\n      }\n      html+='</div>';\n    }\n    html+='<details><summary>Reference inventory and remaining decisions</summary><p>18 existing BOM entries; eight explicit scoped nominations. Ten default/family choices remain unresolved without revoking their existing approvals.</p><ul>'+(validationData.inventory||[]).filter(r=>r.project===state.project).map(r=>'<li><button class=\"small-link\" data-open=\"'+esc(r.reference.assetID)+'\">'+esc(r.label)+'</button> · '+esc(r.recordedSelection||'Default nomination unresolved')+' · '+esc(r.scope)+' · family '+esc(r.familyID||'unreconciled')+'</li>').join('')+'</ul><p>'+validationData.gaps.map(esc).join(' ')+'</p>';\n    for(const pet of (validationData.petCandidates||[]).filter(p=>byID.get(p.assetID)?.project===state.project))html+='<button class=\"pill\" data-open=\"'+esc(pet.assetID)+'\">Existing dog candidate · not nominated</button>';\n    return html+'</details><p><a href=\"'+esc(href('REFERENCE_VALIDATION_GUIDE.txt'))+'\" target=\"_blank\" rel=\"noopener\">Evidence, reviewer and backup guide</a></p></section>';\n  }\n"''')
guide=json.loads(r'''"CFA REFERENCE VALIDATION — ENGINEERING AND REVIEWER GUIDE\nVersion 2026-10-13.1. Authored by CFA Site Index, October 13, 2026.\nCanonical sources: REFERENCE_POLICY.txt; collaborators/PRODUCTION_METHOD_20261012.txt;\ncollaborators/character_head_reference_standard.txt; the engineering foundation\nREFERENCE_VALIDATION_FOUNDATION_85326dc2-9270-466c-9e02-aa7df3286206.json.\nThis guide implements their scoped evidence requirements; it changes no artistic acceptance.\n\nHOW TO READ THE BADGES\nCharacter and Scene are independent from their existing stars, favorite, triage,\ncreative lane, manual stage and human acceptance. Legacy Verification remains\na manual stage; it is never converted to an AI pass.\nNot checked / Pass / Fail / Uncertain are assessment results. Required / Optional /\nN/A is separate applicability. N/A is not pass. Pass is always for the named scope.\nA missing original, missing nominated reference, required occluded detail, unknown\ncriteria, changed hash/version/scope or stale tolerance cannot yield a current pass.\nRequired jewelry cannot be waived as asymmetry. Use the documented variant and\nplacement tolerances; optional accessories remain separate. A detail crop cannot\nvalidate a whole actor, a scene or motion.\n\nCOMPARE ACTUAL IMAGES\nChoose an existing scoped nomination and criteria. Inspect the original target\nand original reference. Record each required criterion: visible/occluded/missing/\nunknown, pass/fail/uncertain/not checked, and concrete observations. A filename,\nprovider \"good\", file decode, star score or contact-sheet thumbnail is not a pass.\nRecord target and reference exact IDs, SHA256 and immutable sha256: version;\ncriteria ID/version/digest; named scope; actually seen image IDs/hashes/version;\nreviewer, actual model (or human), surface, time; evidence, uncertainty and provenance.\nDo not claim to have viewed a reference because it was listed in a packet.\nCurrent beta includes only seven originals actually viewed by Site Index.\nNova PA's 21 full-size observations remain separately attributed and are not\nconverted to formal passes. DeepSeek deepseek-v4-pro's reported setup explicitly\ndoes not declare image input; no DeepSeek visual grades were imported. Its B1/B2\ntext work is separate, and no model switch or calibration is activated.\n\nPERSISTENCE AND HISTORY\nEvidence has an independent cfa-reference-validation-v1 browser key and append-only\nassessment IDs. Re-importing the same ID/content is harmless; conflicting content\nis rejected atomically. New assessments retain older history. The current badge\nshows the latest axis entry; inspect history for scope and other assessments.\nReadiness requires the latest current pass for each exact declared scope.\nExport validation evidence creates a standalone portable file. Full Save review\nfile / Export review includes validationEvidence and legacyReviewArchive.\nOld imports do not clear evidence. Raw canonical/browser/import review records\nare archived losslessly outside normalizedReview, whose existing operational\nfield handling remains unchanged. Existing review/favorites/basket keys remain.\nUnknown or corrupt evidence storage is retained and blocks evidence replacement;\nexport the original unread backup before resolving it. Storage failure means\ncurrent page state is not durable: export before closing.\nA downloaded/exported record is not host intake or notification. One site owner\npublishes vetted source metadata via build_catalog.py. No watcher is installed.\n\nREADINESS AND REFERENCE MAP\nThe old human scene gate remains separate. Technical readiness additionally needs\na versioned per-scene/use declaration with exact required target/axis/criteria/scope\nchecks, and every check must currently pass. No declared set means unresolved,\nnot an empty-set success. No scene-use declarations were invented by this beta.\nThe 18 existing BOM entries retain acceptance evidence. Eight explicit nominations\nhave criteria transcribed from current scoped policies; ten default choices,\nfamily IDs and derivative gaps remain open. No new gold/reference actor/pet chosen.\nHon cockpit consistency is required only where explicitly locked; existing\nscene-specific Falcon use does not establish a universal set. Lisan environments\nremain open unless explicitly locked. Located dog candidates are not nominated.\nSource updates must bump criteria versions and recompute the criteria digest.\nThe builder checks pinned policy and reference bytes before publication. Prior\nevidence is retained and displays stale if its target/reference/criteria changes.\n\nMOUTH COVERAGE\nRecipe input readiness and optional artwork coverage are different. The verified\nCantina v004 graph uses WanAnimateToVideo / Wan2.2 Animate Mix: one actor still,\nCLIP Vision, aligned face/pose/background sequences and mask. It requires zero\nstill-atlas slots. Audio enters CreateVideo; the final composite protects/restores\nthe source mouth. It does not prove newly generated speech or rap lip-sync.\nThe reported face-only DWPose versus RGB-face-crop representation concern remains\nunresolved until actual runtime frames/contract are inspected. No graph changed.\nHon's dated art plan has 50 macros plus 130 unique head-state/view slots per look.\nOptional pitch adds 40 (170 unique heads, not 190). Key-state selection is not\naccepted. Lisan's inherited optional art plan has 49 numbers, skipping Hon's\nchain-bite #47. No universal viseme count or automatic bank expansion follows.\nKeep articulation, expression/action, yaw, pitch, identity/dental revision,\ngrill/breather/lip rings and props separate. Counts are source hashes and provider\nlabels, not independently distinct usable poses. Multiple takes do not add slots.\nSeven Lisan human Production mouth details cover five labels; all old reviews\nremain. The 38 R2 retries and three later optional grill repairs are received,\nunchecked candidates. Their malformed CSV note quoting is preserved in originals;\nthe typed intake verifies the final digest tokens/SHA256SUMS and source bytes.\nStatic validation does not establish temporal speech. A later bounded clip needs\na chosen audio-driven route or synchronized driving performance, exact track\nexcerpt/timebase/FPS, visible needed mechanics, sound+picture and frame inspection,\nand per-look/phrase evidence. No run, spend, timing acceptance or launch is authorized.\n\nROLLBACK AND OWNERSHIP\nFresh source snapshots and catalog.before.js are in\ncollaborators/site_publication_20261013/reference_validation_20261013/source_before.\nFor rollback, compare current hashes against the final report first, preserve\nnewer changes and both browser/portable evidence backups, then remove only this\nfeature's scoped integration and rebuild through the single publisher.\nDo not restore whole files over concurrent edits or delete review/evidence storage.\nCFA Site Index owns implementation and local publication. CFA Nova owns production\nsemantics, intake/registry and central production/carepack routing. Claude owns\ncreative criteria and his authored guidance. The owner follow-up packet proposes\ncrosslinks for those sources without rewriting their authorship or claiming delivery.\nPan teaching return: extend the existing reference-role, static mouth and video/audio\nlessons; teach observed-versus-reported, scoped comparisons, zero-atlas graph inputs\nand static-versus-temporal evidence. Do not duplicate the curriculum.\n"''')
